<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\AuditService;Auth::requirePermission('AUDIT_VIEW_ALL');$q=trim((string)($_GET['q']??''));$rows=AuditService::events($q);$pageTitle='Audit Events';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Audit events</h1><p>Search important workflow and security actions.</p></div><span class="badge">Read only</span></div><form method="get" class="card"><div class="field"><label>Action, user or metadata</label><input name="q" value="<?=h($q)?>"></div><div class="actions"><button class="button">Search</button></div></form><div class="card table-wrap" style="margin-top:18px"><table><thead><tr><th>Time</th><th>Action</th><th>Entity</th><th>Actor</th><th>Details</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['created_at'])?></td><td><?=h($r['resolved_action']?:'Unclassified')?></td><td><?=h(($r['resolved_entity']?:'').' '.($r['entity_id_value']?:''))?></td><td><?=h($r['actor_name']?:'System')?></td><td><code><?=h($r['metadata_json'])?></code></td></tr><?php endforeach;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';?>